//
// Demultiplex Illumina BCL data using bcl-convert or bcl2fastq
//

include { BCLCONVERT } from "nf-core/bclconvert"
include { BCL2FASTQ  } from "nf-core/bcl2fastq"
include { MULTIQCSAV } from "nf-core/multiqcsav"

workflow BCL_DEMULTIPLEX {
    take:
    ch_flowcell // [[id:"", lane:""], samplesheet.csv, path/to/bcl/files]
    demultiplexer // bclconvert or bcl2fastq

    main:
    ch_fastq_with_meta = channel.empty()
    ch_reports = channel.empty()
    ch_stats = channel.empty()
    ch_interop = channel.empty()
    ch_logs = channel.empty()
    ch_sav_files = channel.empty()
    ch_undetermined  = channel.empty()
    ch_autodetect_samplesheet = channel.empty()

    // MODULE: bclconvert
    // Demultiplex the bcl files
    if (demultiplexer == "bclconvert") {
        BCLCONVERT(ch_flowcell)
        ch_interop = ch_interop.mix(BCLCONVERT.out.interop)
        ch_reports = ch_reports.mix(BCLCONVERT.out.reports)
        ch_logs = ch_logs.mix(BCLCONVERT.out.logs)
        ch_undetermined = ch_undetermined.mix(BCLCONVERT.out.undetermined)
        ch_sav_files = ch_sav_files.mix(BCLCONVERT.out.reports)
        ch_autodetect_samplesheet = ch_autodetect_samplesheet.mix(BCLCONVERT.out.autodetect_samplesheet)
        ch_fastq_with_meta = ch_fastq_with_meta.mix(
            generateReadgroupBCLCONVERT(
                BCLCONVERT.out.reports.map { meta, reports ->
                    return [meta, file(reports).resolve("fastq_list.csv")]
                },
                BCLCONVERT.out.fastq,
            )
        )
    }

    // MODULE: bcl2fastq
    // Demultiplex the bcl files
    if (demultiplexer == "bcl2fastq") {
        BCL2FASTQ(ch_flowcell)
        ch_interop = ch_interop.mix(BCL2FASTQ.out.interop)
        ch_reports = ch_reports.mix(BCL2FASTQ.out.reports)
        ch_stats = ch_stats.mix(BCL2FASTQ.out.stats)
        ch_undetermined = ch_undetermined.mix(BCL2FASTQ.out.undetermined)
        ch_sav_files = ch_sav_files.mix(BCL2FASTQ.out.stats)
        ch_fastq_with_meta = ch_fastq_with_meta.mix(
            generateReadgroupBCL2FASTQ(
                BCL2FASTQ.out.fastq
            )
        )
    }

    // MODULE: multiqcsav
    ch_mqcsav_input = ch_flowcell
        .map { meta, _samplesheet, flowcell ->
            def interopDir = file(flowcell).resolve("InterOp")
            def interop = file(interopDir).exists() ? files("${interopDir}/*.bin") : []
            def xml = files(file(flowcell).resolve("*.xml"), checkIfExists: true)
            return [meta, xml, interop]
        }
        .join(ch_sav_files, by: 0)
        .map { meta, xml, interop, reports ->
            return [meta - meta.subMap(['lane']), xml, interop, reports]
        }
        .groupTuple(by: [0])
        .map { meta, xml, interop, reports ->
            return [meta, xml.flatten().unique(), interop.flatten().unique(), reports.flatten().unique(), [], [], [], []]
        }
        .dump(tag: "MULTIQC SAV input", pretty: true)

    // MULTIQCSAV([meta, xml, interop, reports, multiqc_config, multiqc_logo, [], []])
    MULTIQCSAV(ch_mqcsav_input)

    // extract empty fastq files from channel
    ch_fastq = ch_fastq_with_meta.branch { meta, fastq ->
        empty: fastq.any { fq -> file(fq).size() < 30 }
        return [meta, fastq]
        fastq: true
        return [meta, fastq]
    }

    emit:
    fastq           = ch_fastq.fastq
    empty_fastq     = ch_fastq.empty
    reports         = ch_reports
    stats           = ch_stats
    interop         = ch_interop
    logs            = ch_logs
    undetermined    = ch_undetermined
    sav_report      = MULTIQCSAV.out.report
    sav_data        = MULTIQCSAV.out.data
    sav_plots       = MULTIQCSAV.out.plots
    autodetect_samplesheet = ch_autodetect_samplesheet
}

def generateReadgroupBCLCONVERT(ch_fastq_list_csv, ch_fastq) {
    return ch_fastq_list_csv
        .join(ch_fastq, by: [0])
        .map { meta, csv_file, fastq_list ->
            return createReadgroupBCLCONVERT(meta, csv_file, fastq_list)
        }
        .flatMap()
}

def createReadgroupBCLCONVERT(meta, csv_file, fastq_list) {
    def fastq_files = fastq_list instanceof List ? fastq_list : [fastq_list]
    def emitted_fastq = [] as Set
    def meta_fastq = []
    csv_file
        .splitCsv(header: true)
        .each { row ->
            // dereference the fastq files in the csv
            def fastq1 = fastq_files.find { fq -> file(fq).name == file(row.Read1File).name }
            def fastq2 = row.Read2File ? fastq_files.find { fq -> file(fq).name == file(row.Read2File).name } : null
            def fastq_key = [fastq1, fastq2].findAll().collect { fq -> file(fq).name }.join("|")

            if (emitted_fastq.add(fastq_key)) {
                // Create the readgroup tuple
                // RGID,RGSM,RGLB,Lane,Read1File,Read2File
                def rg = [:]
                // row.RGID is index1.index2.lane
                rg.ID = row.RGID
                // RGPU is a custom column in the samplesheet containing the flowcell ID
                rg.PU = row.RGPU ? row.RGPU : meta.id + "." + row.Lane
                rg.SM = row.RGSM
                rg.LB = row.RGLB ? row.RGLB : ""
                rg.PL = "ILLUMINA"

                // set fastq metadata
                def new_meta = meta + [id: fastq1.getSimpleName().toString() - ~/_R[0-9]_001.*$/, readgroup: rg, single_end: !fastq2]

                meta_fastq << [new_meta, fastq2 ? [fastq1, fastq2] : [fastq1]]
            }
        }
    return meta_fastq
}

def generateReadgroupBCL2FASTQ(ch_fastq) {
    ch_fastq
        .transpose()
        .map { fc_meta, fastq ->
            def meta = [:]
            meta.id = fastq.getSimpleName().toString() - ~/_R[0-9]_001.*$/
            meta.samplename = fastq.getSimpleName().toString() - ~/_S[0-9]+.*$/
            meta.fcid = fc_meta.id
            meta.lane = fc_meta.lane
            // The buffered input stream allows reading directly from cloud storage
            // It will not make a local copy of the file.
            def line = ""
            fastq.withInputStream { fq ->
                def gzipStream = new java.util.zip.GZIPInputStream(fq)
                def decoder = new InputStreamReader(gzipStream, 'ASCII')
                def buffered = new BufferedReader(decoder)
                line = buffered.readLine()
                buffered.close()
            }
            if (line != null && line.startsWith('@')) {
                line = line.substring(1)
                // expected format is like:
                // xx:yy:FLOWCELLID:LANE:... (seven fields)
                def fields = line.split(':')
                // CASAVA 1.8+ format, from  https://support.illumina.com/help/BaseSpace_OLH_009008/Content/Source/Informatics/BS/FileFormat_FASTQ-files_swBS.htm
                // "@<instrument>:<run number>:<flowcell ID>:<lane>:<tile>:<x-pos>:<y-pos>:<UMI> <read>:<is filtered>:<control number>:<index>"
                //def sequencer_serial = fields[0]
                //def run_nubmer       = fields[1]
                def fcid = fields[2]
                def lane = fields[3]
                def index = fields[-1] =~ /[GATC+-]/ ? fields[-1] : ""
                def ID = [index, lane].join(".")
                def LB = ""
                def PL = "ILLUMINA"
                def PU = [fcid, lane].findAll().join(".")
                def SM = fastq.getSimpleName().toString() - ~/_S[0-9]+.*$/
                meta.readgroup = ["ID": ID, "SM": SM, "PL": PL, "PU": PU, "LB": LB]
            }
            else {
                println("No reads were found in FASTQ file: ${fastq}")
                meta.readgroup = [:]
            }
            return [meta, fastq]
        }
        .groupTuple(by: [0])
        .map { meta, fastq ->
            meta.single_end = fastq.size() == 1
            return [meta, fastq.flatten()]
        }
}

// nf-core subworkflows test bcl_demultiplex
nextflow_workflow {

    name "Test Subworkflow test_bcl_demultiplex_bclconvert"
    script "../main.nf"
    config "./nextflow.config"
    workflow "BCL_DEMULTIPLEX"

    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/bcl_demultiplex"
    tag "bclconvert"
    tag "bcl2fastq"
    tag "multiqcsav"

    test("bclconvert") {
        def run_dir
        setup {
            run_dir = extract('https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/genomics/sarscov2/illumina/bcl/200624_A00834_0183_BHMTFYDRXX.tar.gz').resolve('200624_A00834_0183_BHMTFYDRXX')
        }

        when {
            workflow {
                """
                input[0] = channel.of([[id:'HMTFYDRXX', lane:1], file("https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/genomics/sarscov2/illumina/bcl/SampleSheet.csv"), file('${run_dir}')])
                input[1] = "bclconvert"
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                    sanitizeOutput(workflow.out, unstableKeys: ["empty_fastq", "logs", "sav_report", "sav_data", "sav_plots", "undetermined"]).collectEntries { key, val ->
                        if (key == "interop") {
                            return [ key, val.collect { meta, files ->
                                [
                                    meta,
                                    files.collect { interop_file ->
                                        if (interop_file.endsWith("IndexMetricsOut.bin")) {
                                            file(interop_file).name
                                        } else {
                                            interop_file
                                        }
                                    }
                                ]
                            } ]
                        }
                        return [ key, val ]
                    },
                    ).match()
                },
            )
        }
    }

    test("bcl2fastq") {
        def run_dir
        setup {
            run_dir = extract('https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/genomics/homo_sapiens/illumina/bcl/flowcell.tar.gz').resolve('220422_M11111_0222_000000000-K9H97')
        }

        when {
            workflow {
                """
                input[0] = channel.of([[id:'test', lane:1 ], file("https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/genomics/homo_sapiens/illumina/bcl/flowcell_samplesheet.csv"), file('${run_dir}')])
                input[1] = "bcl2fastq"
                """
            }
        }

        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(
                    sanitizeOutput(workflow.out, unstableKeys: ["empty_fastq", "logs", "reports", "sav_report", "sav_data", "sav_plots", "stats", "undetermined"]).collectEntries { key, val ->
                        if (key == "interop") {
                            return [ key, val.collect { meta, files ->
                                [
                                    meta,
                                    files.collect { interop_file ->
                                        if (interop_file.endsWith("IndexMetricsOut.bin")) {
                                            file(interop_file).name
                                        } else {
                                            interop_file
                                        }
                                    }
                                ]
                            } ]
                        }
                        return [ key, val ]
                    },
                    ).match()
                },
            )
        }
    }
}

